    node06Remains: { en: "A sea I want to keep for life.", zh: "想一生保留的海。", ko: "평생 간직하고 싶은 바다。", ja: "一生残したい海。", es: "Un mar que quiero guardar toda la vida.", fr: "Une mer que je veux garder toute la vie." },
