    node07Place: { en: "PERSONAL COMPANY ·", zh: "个人公司", ko: "개인 회사 ·", ja: "個人会社 ·", es: "EMPRESA PERSONAL ·", fr: "SOCIÉTÉ PERSONNELLE ·" },
    node07Happened: { en: "Lazyland, swimwear, content, knowledge base and AI systems grow at once.", zh: "懒懒岛、泳衣、内容、知识库与 AI 系统同时生长。", ko: "라지랜드, 수영복, 콘텐츠, 지식베이스, AI 시스템이 동시에 자란다。", ja: "ラジランド、水着、コンテンツ、知識ベース、AI システムが同時に育つ。", es: "Lazyland, ropa de baño, contenido, base de conocimiento y sistemas de IA crecen a la vez.", fr: "Lazyland, maillots, contenus, base de connaissances et systèmes d’IA poussent ensemble." },
    node07Changed: { en: "Began turning experience into assets and freedom into a sustainable structure.", zh: "开始把经历变成资产，把自由变成可持续结构。", ko: "경험을 자산으로, 자유를 지속 가능한 구조로 바꾸기 시작했다。", ja: "経験を資産に、自由を持続可能な構造に変え始めた。", es: "Empecé a convertir la experiencia en activos y la libertad en una estructura sostenible.", fr: "J’ai commencé à transformer l’expérience en actifs et la liberté en structure durable." },
    node07Remains: { en: "A world still unfinished, but no longer starting from zero.", zh: "一个仍未完成、但不再从零开始的世界。", ko: "아직 끝나지 않았지만 다시 zero에서 시작하지 않는 세계。", ja: "まだ終わっていないが、もうゼロから始まらない世界。", es: "Un mundo aún inacabado, pero que ya no empieza de cero.", fr: "Un monde encore inachevé, mais qui ne recommence plus de zéro." },
    node07PhotoAlt: { en: "Faye Duoduo name card", zh: "臧世沅 Faye 多多 个人名片", ko: "장세원 Faye 두두 명함", ja: "蔵世沅 Faye 多多 名刺", es: "Tarjeta de Faye Duoduo (Zang Shiyuan)", fr: "Carte de visite de Faye Duoduo (Zang Shiyuan)" },
