    rootsQuoteEn1: { en: "Freedom is not the absence of roots.", zh: "", ko: "자유는 뿌리의 부재가 아니다。", ja: "自由は根の不在ではない。", es: "La libertad no es la ausencia de raíces.", fr: "La liberté n’est pas l’absence de racines." },
    rootsQuoteEn2: { en: "It is learning to grow roots you can carry with you.", zh: "", ko: "지닐 수 있는 뿌리를 기르는 법을 배우는 것이다。", ja: "持ち運べる根を育てることを 배우는 것이다。", es: "Es aprender a cultivar raíces que puedes llevar contigo.", fr: "C’est apprendre à cultiver des racines que l’on peut emporter." },
    rootsQuoteZh1: { en: "自由不是没有根，", zh: "自由不是没有根，", ko: "자유는 뿌리가 없는 것이 아니라，", ja: "自由は根がないことではなく，", es: "La libertad no es no tener raíces,", fr: "La liberté n’est pas le manque de racines," },
    rootsQuoteZh2: { en: "而是把根长在可以随身携带的地方。", zh: "而是把根长在可以随身携带的地方。", ko: "오히려 뿌리를 지닐 수 있는 곳에 심는 것이다。", ja: "むしろ根を持ち運べる場所に育てること。", es: "sino plantar raíces en un lugar que puedes llevar contigo.", fr: "mais faire pousser des racines en un lieu que l’on emporte." },
