    methodEarthTitle: { en: "FOLLOW EARTH. NOT CALENDAR.", zh: "跟随自然，而不是日历", ko: "달력보다 자연을 따른다", ja: "暦より自然に従う", es: "SIGUE LA TIERRA, NO EL CALENDARIO", fr: "SUIVRE LA TERRE, PAS LE CALENDRIER" },
    methodEarthCopy: { en: "Reality first; then season, body, project stage, and only then symbolic rhythm.", zh: "先放入现实责任，再看季节、身体与项目阶段，最后才用象征节律优化安排。", ko: "현실의 책임을 먼저 두고 계절, 몸, 프로젝트 단계를 본 뒤 상징적 리듬을 활용한다.", ja: "現実の責任を先に置き、季節・身体・プロジェクト段階を見てから象徴的なリズムを使う。", es: "Primero la realidad; luego estación, cuerpo y fase del proyecto; solo después el ritmo simbólico.", fr: "D’abord la réalité, puis la saison, le corps et l’étape du projet, enfin le rythme symbolique." },
    methodAliveTitle: { en: "THE ALIVE DASHBOARD", zh: "生命力仪表盘", ko: "얼라이브 대시보드", ja: "生命力ダッシュボード", es: "EL PANEL ALIVE", fr: "LE TABLEAU ALIVE" },
    methodAliveCopy: { en: "Review body, creation, relationships, the unknown, work and autonomy from one to five.", zh: "每个阶段用一到五分复盘身体、创造、关系、未知、事业与自主。", ko: "각 단계마다 몸, 창작, 관계, 미지, 일, 자율성을 1점부터 5점까지 돌아본다.", ja: "各段階で身体・創造・関係・未知・仕事・自律を1から5で振り返る。", es: "Revisa cuerpo, creación, relaciones, lo desconocido, trabajo y autonomía del uno al cinco.", fr: "Évaluer de un à cinq le corps, la création, les relations, l’inconnu, le travail et l’autonomie." },
    methodAssetTitle: { en: "EXPERIENCE → ASSET", zh: "把经历变成资产", ko: "경험을 자산으로", ja: "経験を資産へ", es: "EXPERIENCIA → ACTIVO", fr: "EXPÉRIENCE → ACTIF" },
    methodAssetCopy: { en: "Real life becomes a question, experiment, judgment, work, feedback and the beginning of another cycle.", zh: "真实生活变成问题、实验、判断、作品与反馈，再成为下一轮生活的起点。", ko: "현실의 삶이 질문, 실험, 판단, 결과물, 피드백이 되고 다시 다음 순환의 출발점이 된다.", ja: "現実の生活が問い、実験、判断、作品、フィードバックとなり、次の循環の起点になる。", es: "La vida real se convierte en pregunta, experimento, criterio, obra y feedback; luego inicia otro ciclo.", fr: "La vie réelle devient question, expérience, jugement, œuvre et retour, puis le début d’un autre cycle." },
    experimentsSmall: { en: "ACTIVE / TESTING / PAUSED", zh: "", ko: "진행 / 테스트 / 휴면", ja: "進行 / テスト / 休止", es: "ACTIVO / PRUEBA / PAUSADO", fr: "ACTIF / TEST / PAUSÉ" },
