    objectSwimwearItem3: { en: "Sri Lanka test", zh: "Sri Lanka 测试", ko: "스리랑카 테스트", ja: "スリランカ・テスト", es: "Prueba en Sri Lanka", fr: "Test au Sri Lanka" },
    objectPassport: { en: "PASSPORT", zh: "护照", ko: "여권", ja: "パスポート", es: "PASAPORTE", fr: "PASSEPORT" },
    objectPassportLabel: { en: "Passport", zh: "护照", ko: "여권", ja: "パスポート", es: "Pasaporte", fr: "Passeport" },
    objectPassportTitle: { en: "The Long Way West", zh: "", ko: "서쪽으로의 긴 길", ja: "西への長い道", es: "El Largo Camino al Oeste", fr: "La Longue Route vers l’Ouest" },
    objectPassportStatus: { en: "ROUTE ·", zh: "路线", ko: "경로 ·", ja: "ルート ·", es: "RUTA ·", fr: "ROUTE ·" },
    objectPassportCopy: { en: "The passport records arrival, but not how a road changes a person. This route continues west from Central Asia and Turkey; what truly stays is a new judgement.", zh: "护照记录了抵达，却不记录一段路怎样改变一个人。这条路线从中亚、土耳其继续向西，真正留下的是新的判断。", ko: "여권은 도착을 기록하지만 길이 어떻게 사람을 바꾸는지는 기록하지 않는다. 이 경로는 중앙아시아, 튀르키예에서 서쪽으로 이어지고, 진짜로 남는 건 새로운 판단이다。", ja: "パスポートは到着を記録するが、道が人をどう変えるかは記さない。このルートは中央アジア、トルコから西へ続き、本当に残るのは新しい判断。", es: "El pasaporte registra la llegada, pero no cómo un camino cambia a una persona. Esta ruta sigue al oeste desde Asia Central y Turquía; lo que queda es un nuevo juicio.", fr: "Le passeport enregistre l’arrivée, mais pas comment une route change une personne. Cette route continue vers l’ouest depuis l’Asie centrale et la Turquie ; ce qui reste est un nouveau jugement." },
    objectPassportItem1: { en: "Overland crossing", zh: "陆路穿越", ko: "육로 횡단", ja: "陸路の踏破", es: "Cruce por tierra", fr: "Traversée par la terre" },
    objectPassportItem2: { en: "Borders and waiting", zh: "边境与等待", ko: "국경과 대기", ja: "国境と待ち", es: "Fronteras y espera", fr: "Frontières et attente" },
    objectPassportItem3: { en: "Unfamiliar life", zh: "陌生生活", ko: "낯선 생활", ja: "見知らぬ生活", es: "Vida desconocida", fr: "Vie inconnue" },
    objectCamera: { en: "CAMERA", zh: "相机", ko: "카메라", ja: "カメラ", es: "CÁMARA", fr: "APPAREIL PHOTO" },
    objectCameraLabel: { en: "Camera", zh: "相机", ko: "카메라", ja: "カメラ", es: "Cámara", fr: "Appareil photo" },
    objectCameraTitle: { en: "People Along the Way", zh: "", ko: "길 위의 사람들", ja: "道すがらの人々", es: "Gente en el Camino", fr: "Gens sur la Route" },
    objectCameraStatus: { en: "PORTRAITS ·", zh: "人物", ko: "인물 ·", ja: "人物 ·", es: "RETRATOS ·", fr: "PORTRAITS ·" },
    objectCameraCopy: { en: "The camera is not a check-in tool, but a reason to approach strangers. Here are hostel guests, interviewees, and the moments they chose another life.", zh: "相机不是打卡工具，而是靠近陌生人的理由。这里收藏青旅住客、采访对象，以及他们选择另一种生活的瞬间。", ko: "카메라는 체크인 도구가 아니라 낯선 이에게 다가갈 이유다. 여기엔 게스트하우스 투숙객, 인터뷰이, 그리고 다른 삶을 선택한 순간들이 있다。", ja: "カメラは押印ツールではなく、見知らぬ人に近づく理由。ここに収めるのはホステル宿泊客、インタビュー対象、そして別の生を選んだ瞬間。", es: "La cámara no es una herramienta de check-in, sino una razón para acercarse a extraños. Aquí se guardan huéspedes de albergue, entrevistados y los momentos en que eligieron otra vida.", fr: "L’appareil photo n’est pas un outil de check-in, mais une raison d’approcher les inconnus. S’y trouvent hôtes d’auberge, interviewés et les instants où ils ont choisi une autre vie." },
    objectCameraItem1: { en: "Hostel people", zh: "青旅人物", ko: "게스트하우스 인물", ja: "ホステルの人", es: "Gente de albergue", fr: "Gens d’auberge" },
    objectCameraItem2: { en: "Street fragments", zh: "街头片段", ko: "거리의 단편", ja: "街の断片", es: "Fragmentos callejeros", fr: "Fragments de rue" },
    objectCameraItem3: { en: "One conversation", zh: "一次对话", ko: "한 번의 대화", ja: "一度の対話", es: "Una conversación", fr: "Une conversation" },
