    objectRecorderLabel: { en: "Recorder", zh: "录音机", ko: "녹음기", ja: "レコーダー", es: "Grabadora", fr: "Enregistreur" },
    objectRecorderTitle: { en: "Voices from Hostels", zh: "Voices from Hostels", ko: "게스트하우스의 목소리", ja: "ホステルの声", es: "Voces de Albergues", fr: "Voix des Auberges" },
    objectRecorderStatus: { en: "AUDIO ·", zh: "声音", ko: "오디오 ·", ja: "音 ·", es: "AUDIO ·", fr: "AUDIO ·" },
    objectRecorderCopy: { en: "Some stories need breath, pauses and accent kept. The recorder holds voices not yet sorted into articles, and real people on the road.", zh: "有些故事需要保留呼吸、停顿和口音。录音机装着尚未被整理成文章的声音，以及旅途中真实的人。", ko: "어떤 이야기는 호흡, 멈춤, 억양을 간직해야 한다. 녹음기엔 아직 글로 정리되지 않은 소리와 여정 속 진짜 사람이 담겨 있다。", ja: "ある物語は呼吸や間、なまりを残す必要がある。レコーダーにはまだ記事に整えられていない声と、旅の本物の人が入っている。", es: "Algunas historias necesitan conservar el aliento, las pausas y el acento. La grabadora guarda voces aún no ordenadas en artículos, y personas reales del camino.", fr: "Certaines histoires doivent garder le souffle, les pauses et l’accent. L’enregistreur contient des voix pas encore classées en articles, et de vraies personnes du voyage." },
    objectRecorderItem1: { en: "People recordings", zh: "人物录音", ko: "인물 녹음", ja: "人物録音", es: "Grabaciones de personas", fr: "Enregistrements de personnes" },
    objectRecorderItem2: { en: "Ambient sound", zh: "环境声音", ko: "환경 소리", ja: "環境音", es: "Sonido ambiental", fr: "Son ambiant" },
    objectRecorderItem3: { en: "Uncut fragments", zh: "未剪片段", ko: "미편집 조각", ja: "未編集の断片", es: "Fragmentos sin cortar", fr: "Fragments non montés" },
