    objectShellLabel: { en: "Shell", zh: "贝壳", ko: "조개", ja: "貝", es: "Concha", fr: "Coquillage" },
    objectShellTitle: { en: "Found at the Tide Line", zh: "", ko: "조수선에서 주운 것", ja: "潮間帯で拾った物", es: "Encontrado en la Línea de Marea", fr: "Trouvé sur la Ligne de Marée" },
    objectShellStatus: { en: "FOUND ·", zh: "拾得", ko: "주움 ·", ja: "拾得 ·", es: "ENCONTRADO ·", fr: "TROUVÉ ·" },
    objectShellCopy: { en: "Shells, ticket stubs, knots and a page of journal without conclusion are the smallest yet most honest evidence of life in Duoduo’s world.", zh: "贝壳、票根、绳结和一页没有结论的日记，是多多世界里最小、也最诚实的生命证据。", ko: "조개, 티켓 받침, 매듭, 그리고 결론 없는 일기 한 장은 두두 세계에서 가장 작고도 가장 정직한 생명의 증거다。", ja: "貝、切符の半券、結び目、結論のない日記の一ページは、多多の世界で最も小さくもっとも誠実な生命の証拠。", es: "Conchas, boletos, nudos y una página de diario sin conclusión son la evidencia de vida más pequeña y honesta en el mundo de Duoduo.", fr: "Coquillages, tickets, nœuds et une page de journal sans conclusion sont la preuve de vie la plus petite et la plus honnête du monde de Duoduo." },
    objectShellItem1: { en: "Shells and salt", zh: "贝壳与盐", ko: "조개와 소금", ja: "貝と塩", es: "Conchas y sal", fr: "Coquillages et sel" },
    objectShellItem2: { en: "Old tickets", zh: "旧车票", ko: "오래된 차표", ja: "古い切符", es: "Viejos boletos", fr: "Vieux billets" },
    objectShellItem3: { en: "Diary fragments", zh: "日记碎片", ko: "일기 조각", ja: "日記の断片", es: "Fragmentos de diario", fr: "Fragments de journal" },
