    logTitle: { en: "SURF LOG", zh: "冲浪记录", ko: "서핑 기록", ja: "サーフィン記録", es: "REGISTRO DE SURF", fr: "JOURNAL DE SURF" },
    logEntry1Title: { en: "Sri Lanka", zh: "斯里兰卡", ko: "스리랑카", ja: "スリランカ", es: "Sri Lanka", fr: "Sri Lanka" },
    logEntry1Copy: { en: "Kabalana was the right call — right on the sand, the right people, the right vibe. My test for a place is simple: am I trusting my instincts more, and do its people make me want to stay?", zh: "Kabalana 是正确的决定——就在沙滩上，对的人，对的氛围。我判断一个地方的方法很简单：我是否越来越相信自己的直觉，这里的人是否让我想多待？", ko: "Kabalana는 옳은 선택이었다 — 바로 모래사장 위, 맞는 사람들, 맞는 분위기. 한 곳을 판단하는 나의 기준은 단순하다: 직감을 더 믿게 되는가, 그리고 그곳 사람들이 머물고 싶게 만드는가.", ja: "Kabalana は正しい選択だった — 目の前が砂浜で、人も、雰囲気も。場所を判断する僕の基準は単純だ: 直感をより信じられるか、そこの人が居たいと思わせるか。", es: "Kabalana fue la decisión acertada — justo en la arena, la gente adecuada, el vibe correcto. Mi prueba para un lugar es simple: ¿confío más en mi instinto y su gente me hace querer quedarme?", fr: "Kabalana était le bon choix — direct sur le sable, les bonnes personnes, la bonne ambiance. Mon test pour un lieu est simple : ai-je plus confiance en mon instinct, et ses gens me donnent-ils envie de rester ?" },
    logEntry2Title: { en: "Wave Reading", zh: "看浪", ko: "파도 읽기", ja: "波の読み", es: "Lectura de Olas", fr: "Lecture des Vagues" },
    logEntry2Copy: { en: "One movement per break: Hainan for take-off, Bali for duck-diving, Sri Lanka for stance and turns. Every spot differs, yet every spot makes me happy — treat places as a moving practice ground.", zh: "每个浪点只练一个动作：海南练起程，巴厘岛练越浪，斯里兰卡练站姿与转向。每个点都不一样，却都让我快乐——把地点当成流动的练习场。", ko: "브레이크마다 한 동작: 하이난은 이륙, 발리는 돌파, 스리랑카는 자세와 턴. 매 장소는 다르지만 모두 나를 행복하게 한다 — 장소를 움직이는 연습장으로 여겨라.", ja: "一本の波に一つの動き: 海南でテイクオフ、バリで越波、スリランカで姿勢とターン。どの場所も違うが、どれも僕を幸せにする — 場所を動く練習場とせよ。", es: "Un movimiento por rompiente: Hainan para el take-off, Bali para esquivar, Sri Lanka para la postura y los giros. Cada sitio difiere, pero cada sitio me hace feliz — trata los lugares como un terreno de práctica en movimiento.", fr: "Un mouvement par spot : Hainan pour le take-off, Bali pour passer les vagues, Sri Lanka pour la posture et les virages. Chaque spot diffère, mais chacun me rend heureux — fais des lieux un terrain d’entraînement mouvant." },
    logEntry3Title: { en: "Strangers", zh: "采访陌生人", ko: "낯선 사람", ja: "見知らぬ人", es: "Desconocidos", fr: "Inconnus" },
    logEntry3Copy: { en: "The trick to interviewing strangers is catching their words, not firing questions — build a real connection, then let them say something true with ease.", zh: "采访陌生人的诀窍是接住话，而不是抛问题——先建立真实的连接，再让人轻松说出有亮点的真心话。", ko: "낯선 사람을 인터뷰하는 기술은 질문을 던지는 게 아니라 말을 받는 것 — 진짜 연결을 먼저 맺고, 상대가 편하게 진심을 말하게 하라.", ja: "見知らぬ人を取材するコツは質問を浴びせるのでなく言葉を受け止めること — まず本物のつながりを作り、相手が楽に本音を話せるようにする。", es: "El truco para entrevistar desconocidos es recoger sus palabras, no lanzar preguntas — crea una conexión real y deja que digan algo verdadero con soltura.", fr: "Le truc pour interviewer des inconnus est de recueillir leurs mots, pas de lancer des questions — créez un vrai lien, puis laissez-les dire quelque chose de vrai avec aisance." },
    lessonsTitle: { en: "LESSONS ARE COMING WITH THE NEXT TIDE.", zh: "教程会随着下一次潮汐到来。", ko: "다음 조수와 함께 강의가 온다。", ja: "次の潮汐とともにレッスンが来る。", es: "LAS LECCIONES LLEGAN CON LA PRÓXIMA MAREA.", fr: "LES LEÇONS ARRIVENT AVEC LA PROCHAINE MARÉE." },
    wearStatus: { en: "PROTOTYPE BATCH 01", zh: "第一批产品原型", ko: "프로토타입 배치 01", ja: "プロトタイプ・バッチ01", es: "LOTE PROTOTIPO 01", fr: "LOT PROTOTYPE 01" },
    wearTitle: { en: "DUODUO SWIMWEAR", zh: "多多泳衣实验", ko: "두두 수영복 실험", ja: "多多水着実験", es: "EXPERIMENTO DUODUO SWIMWEAR", fr: "EXPÉRIENCE DUODUO SWIMWEAR" },
    wearCopy: { en: "Not a finished brand yet: twenty first samples, a fit problem to solve, and a real test between China and Sri Lanka.", zh: "它还不是一个成熟品牌：目前有20件第一版样品、一个必须先解决的版型舒适度问题，以及连接中国和斯里兰卡市场的真实测试。", ko: "아직 완성된 브랜드가 아니다. 첫 샘플 20벌, 해결해야 할 핏 문제, 중국과 스리랑카 사이의 실제 테스트가 있다.", ja: "まだ完成したブランドではない。最初のサンプル20着、解決すべきフィットの問題、中国とスリランカをつなぐ実地テストがある。", es: "Aún no es una marca terminada: veinte primeras muestras, un problema de ajuste y una prueba real entre China y Sri Lanka.", fr: "Ce n’est pas encore une marque aboutie : vingt premiers échantillons, un problème de coupe à résoudre et un test réel entre la Chine et le Sri Lanka." },
    wearTest1: { en: "20 FIRST SAMPLES", zh: "20件第一版样品", ko: "첫 샘플 20벌", ja: "最初の20サンプル", es: "20 PRIMERAS MUESTRAS", fr: "20 PREMIERS ÉCHANTILLONS" },
    wearTest2: { en: "5–8 BODY TESTERS", zh: "5—8位不同身材测试者", ko: "5–8명 체형 테스트", ja: "5〜8人の体型テスト", es: "5–8 CUERPOS DE PRUEBA", fr: "5–8 TESTEUSES" },
    wearTest3: { en: "FIT BEFORE BRAND", zh: "先解决舒适度，再扩大品牌", ko: "브랜드보다 핏 먼저", ja: "ブランドよりフィットが先", es: "AJUSTE ANTES QUE MARCA", fr: "LA COUPE AVANT LA MARQUE" },
    wearLink: { en: "OPEN THE ORIGIN STORY ↗", zh: "回旅行箱看它如何开始 ↗", ko: "시작 이야기 열기 ↗", ja: "始まりの物語を見る ↗", es: "ABRIR LA HISTORIA DE ORIGEN ↗", fr: "OUVRIR L’HISTOIRE D’ORIGINE ↗" },
