    askProvider: { en: "LIVE · CLOUDFLARE WORKERS AI · LLAMA 3.2", zh: "真实 AI · Cloudflare 开放模型", ko: "라이브 · CLOUDFLARE WORKERS AI", ja: "LIVE · CLOUDFLARE WORKERS AI", es: "LIVE · CLOUDFLARE WORKERS AI", fr: "LIVE · CLOUDFLARE WORKERS AI" },
    tool1Title: { en: "Life Reset Questions", zh: "人生重启问题", ko: "삶 재설정 질문", ja: "人生リセットの問い", es: "Preguntas de Reinicio de Vida", fr: "Questions de Réinitialisation de Vie" },
    tool1Copy: { en: "Tell what you truly want to leave: a place, a job, or a way of repeating.", zh: "判断你真正想离开的，是地点、工作，还是一种重复方式。", ko: "진짜 떠나고 싶은 게 장소인지, 일인지, 반복 방식인지 판단한다。", ja: "本当に離れたいのが場所か、仕事か、繰り返し方かを判別する。", es: "Juzga si lo que realmente quieres dejar es un lugar, un trabajo o una forma de repetir.", fr: "Distingue ce que tu veux vraiment quitter : un lieu, un travail ou une façon de répéter." },
    tool2Title: { en: "Personal Context Starter", zh: "个人 Context 起步模板", ko: "개인 컨텍스트 시작기", ja: "個人コンテキスト起動", es: "Iniciador de Contexto Personal", fr: "Amorce de Contexte Personnel" },
    tool2Copy: { en: "Build a personal background starting point for AI that does not overwrite your own language.", zh: "为 AI 建立一个不覆盖你本人语言的个人背景起点。", ko: "AI를 위해 당신의 언어를 덮어쓰지 않는 개인 배경 시작점을 만든다。", ja: "あなたの言葉を上書きしない、AI のための個人背景の起点を作る。", es: "Crea para la IA un punto de partida de contexto personal que no sobrescribe tu propio lenguaje.", fr: "Crée pour l’IA un point de départ de contexte personnel qui ne recouvre pas ton propre langage." },
    tool3Title: { en: "Experiment Review", zh: "个人实验复盘", ko: "실험 리뷰", ja: "実験レビュー", es: "Revisión de Experimentos", fr: "Revue d’Expériences" },
    tool3Copy: { en: "Separate what happened, how I understood it, and what to verify next.", zh: "区分发生了什么、我怎么理解，以及下一步要验证什么。", ko: "무슨 일이 났는지, 내가 어떻게 이해했는지, 다음에 검증할 것을 나눈다。", ja: "何が起きたか、どう理解したか、次に検証することを分ける。", es: "Separa qué pasó, cómo lo entendí y qué verificar a continuación.", fr: "Sépare ce qui est arrivé, comment je l’ai compris et quoi vérifier ensuite." },
